"""Private control rows and references to the exact IDs regenerated by native sync."""

import json
import sys

import frappe

frappe.init(site="tiberio.localhost", sites_path="/home/frappe/frappe-bench/sites")
frappe.connect()
frappe.set_user("Administrator")
prior_ids = json.load(sys.stdin)
try:
	controls = {}
	for doctype in ("DocPerm", "Custom DocPerm", "User Permission", "DocShare", "Has Role"):
		controls[doctype] = frappe.db.sql("SELECT * FROM `tab" + doctype + "`", as_dict=True)
	fields = frappe.get_all(
		"DocField", filters={"fieldtype": ["in", ["Link", "Dynamic Link"]]},
		fields=["parent", "fieldname", "fieldtype", "options"],
	)
	fields += [
		frappe._dict(parent=row.dt, fieldname=row.fieldname, fieldtype=row.fieldtype, options=row.options)
		for row in frappe.get_all(
			"Custom Field", filters={"fieldtype": ["in", ["Link", "Dynamic Link"]]},
			fields=["dt", "fieldname", "fieldtype", "options"],
		)
	]
	references, foreign_keys = [], {}
	for target in ("Has Role", "DocPerm"):
		extra = prior_ids.get(target, []) if isinstance(prior_ids, dict) else (prior_ids if target == "Has Role" else [])
		ids = sorted({row["name"] for row in controls[target]} | set(extra))
		for field in fields:
			if field.fieldtype == "Link" and field.options != target:
				continue
			meta = frappe.get_meta(field.parent)
			if meta.issingle:
				value = frappe.db.get_single_value(field.parent, field.fieldname)
				if value in ids and (field.fieldtype == "Link" or frappe.db.get_single_value(field.parent, field.options) == target):
					references.append({"target": target, "doctype": field.parent, "field": field.fieldname, "count": 1})
				continue
			if not frappe.db.table_exists(field.parent) or not frappe.db.has_column(field.parent, field.fieldname):
				continue
			filters = {field.fieldname: ["in", ids]}
			if field.fieldtype == "Dynamic Link":
				if not field.options or not frappe.db.has_column(field.parent, field.options):
					continue
				filters[field.options] = target
			count = frappe.db.count(field.parent, filters)
			if count:
				references.append({"target": target, "doctype": field.parent, "field": field.fieldname, "count": count})
		foreign_keys[target] = frappe.db.sql(
			"SELECT COUNT(*) FROM information_schema.KEY_COLUMN_USAGE WHERE REFERENCED_TABLE_SCHEMA=DATABASE() AND REFERENCED_TABLE_NAME=%s", "tab" + target
		)[0][0]
	print(json.dumps({"controls": controls, "live_link_references": references, "foreign_keys_to_has_role": foreign_keys["Has Role"], "foreign_keys_by_control": foreign_keys}, default=str))
finally:
	frappe.db.rollback()
	frappe.destroy()
